exercises.solution:
export function rtoSeconds(heartbeatSec, missedBeats, promoteSec, dnsTtlSec) {
  return heartbeatSec * missedBeats + promoteSec + dnsTtlSec;
}

export function failoversWithinBudget(budgetMinutesPerMonth, rtoSec) {
  return Math.floor((budgetMinutesPerMonth * 60) / rtoSec);
}

